mapper.select:
select distinct u.user_id from sys_user u inner join sys_user_role ur on u.user_id = ur.user_id inner join sys_role r on ur.role_id = r.role_id left join worker_skill ws on ws.worker_id = u.user_id where u.status = '0' and u.del_flag = '0' and r.status = '0' and r.del_flag = '0' and r.role_key = 'worker'
and ws.community_id = #{communityId}
order by u.user_id

select user_id from sys_user
where del_flag = '0' and phonenumber = #{phonenumber}
limit 1

select role_id from sys_role
where del_flag = '0' and status = '0' and role_key = #{roleKey}
limit 1
